-- Issue #603 WI-05 — the semantic half of the two `mcp_open_*` candidate
-- probes, as a `clickhouse local` fixture.
--
-- The Rust unit tests in `reclaim_mcp_open.rs` assert the *text* of each
-- probe's conjuncts: delete one and a named test fails. They cannot assert what
-- the conjunct does, because that needs a server.
--
-- NOTHING IN `cargo test` RUNS THIS. `the_fixture_files_are_this_builds_
-- statements_verbatim` compares generated strings against the checked-in files
-- here; it starts no ClickHouse. Plan §7.2's `reclaim-orphan` and
-- `reclaim-generation` live gates are where this becomes automated, and they
-- are **unwritten** — grep finds no such test in the tree — not merely unrun.
-- Docker is unavailable on the reference host, so a sandbox could not have run
-- them either. This fixture is what was actually executed, by hand, and it is
-- checked in so the next reader can execute it too.
--
-- Reproduce (ClickHouse 25.12.5.44, the version-matched binary the stack ships):
--
--   CH=~/.local/lib/moraine/clickhouse/current/bin/clickhouse
--   D=$(mktemp -d)
--   "$CH" local --path "$D" --multiquery < fixture.sql
--   "$CH" local --path "$D" --multiquery < expected/orphan.sql
--   "$CH" local --path "$D" --multiquery < expected/retired.sql
--   "$CH" local --path "$D" --multiquery < expected/delete.sql   # deletes, then census
--
-- `expected/delete.sql` runs THIS BUILD's delete statements for every unit the
-- two probes above return, then prints the survivor census. It exists because
-- the deletes are the only statements here that can destroy live data and
-- nothing used to execute one: a predicate that *widened* — appending
-- ` OR session_id = {session}` to the child arm — left the whole workspace
-- green while emptying four generations of L-RETIRE.
--
-- Its DELETEs are generated by instantiating the shipped predicates over the
-- hand-maintained `FIXTURE_UNITS` list, which makes the file blind in the *add*
-- direction on its own: a probe that starts returning a unit the list omits
-- produces a file with no statement for it, and the census below then prints
-- that session as intact for a build that destroys it. Under the pre-P6 probe
-- that is exactly what happened with `A1B 60`. So `expected/delete.sql` now
-- opens with two `throwIf` statements that run THIS BUILD's probes and compare
-- their output to the list, before any delete. On disagreement the file aborts
-- with `FIXTURE_UNITS no longer matches …` and a non-zero exit (ClickHouse
-- reports 139 for an aborted `local --multiquery` run on macOS), having
-- deleted nothing — verified 2026-07-28 by dropping one unit from the expected
-- array and re-running: the census afterwards showed every fixture row intact.
--
-- Expected survivor census (executed 2026-07-28):
--   session_id  headers turns events
--   A1B         2       1     2     <- the two-headers-one-generation live
--                                      snapshot, fully intact (P6)
--   L-FRESH     2       0     0
--   L-NOPTR     2       0     0
--   L-RETIRE    3       0     3     <- generations 50 and 53 collected; the
--                                      live 60, plus 51 and 52, survive
--   L-STALEPTR  2       0     0
--   L-UNPUB     2       0     0
--   o-fresh     0       0     1
--   o-headered  1       0     1
--   o-planned   0       0     1     <- generation 103 (in-flight plan) kept,
--                                      104 collected
--   o-tombstoned 1      0     1
--   and o-collect / o-plandone / o-turnsonly gone entirely.
--
-- The two probe files are `orphan_candidate_sql("moraine", 86400, 512)` and
-- `retired_lineage_candidate_sql("moraine", 86400, 512)` verbatim, with
-- `FORMAT JSONEachRow` swapped for `FORMAT TSVWithNames`.
--
-- Expected orphan output (executed 2026-07-28):
--   o-collect   100  2 events  1 turn
--   o-plandone  105  1 event            (a COMPLETE plan protects nothing)
--   o-planned   104  1 event            (the session's in-flight plan names 103)
--   o-turnsonly 107            1 turn   (a turns-only pair; header-derived
--                                        probes cannot see it at all)
--   and NOT o-headered/101, o-fresh/102, o-planned/103, o-tombstoned/106.
--
-- Expected retirement output (executed 2026-07-28):
--   L-RETIRE 50  1 event 1 turn 1 header
--   L-RETIRE 53                 1 header   (a childless tombstone unit)
--   and NOT L-RETIRE/51 (a reader can still select it), /52 (same lineage —
--   the existing reclaimer owns it), /60 (live), nor anything from L-UNPUB,
--   L-NOPTR, L-FRESH or L-STALEPTR.
--
-- The mutation ledger these cases witness is in the PR description; each row
-- was produced by editing the probe text here and re-running the two commands
-- above.
--
-- ## The DDL below is NOT the schema of record
--
-- "Verbatim" above is a claim about the two probe files and
-- `expected/delete.sql`, not about these `CREATE TABLE`s. Each table here is
-- **reduced to the columns the probes read** — `mcp_open_publication_headers`
-- ships eighteen more columns than the ten below, and
-- `v_current_published_source_generations` is a *view* in production, stood in
-- for here by a table because `clickhouse local` has nothing to derive it
-- from. `sql/027`, `sql/033` and `sql/034` are the schema of record.
--
-- What *is* faithful is every sort key, because a probe's cost and a
-- `ReplacingMergeTree`'s collapse both depend on it: each `ORDER BY` and
-- `PARTITION BY` below is the shipped one for that table. `mcp_open_events`
-- accordingly carries `source_host` — a column no probe reads — purely so its
-- key is `sql/033`'s `(event_uid, slot, source_host, candidate_generation)`
-- and not a three-column abbreviation of it.

CREATE DATABASE IF NOT EXISTS moraine;

CREATE TABLE moraine.mcp_open_events (
  event_uid String, slot UInt8, source_host String, generation UInt64,
  candidate_generation UInt64,
  session_id String, projected_at DateTime64(3) DEFAULT now64(3)
) ENGINE = ReplacingMergeTree(generation)
PARTITION BY cityHash64(event_uid) % 64
ORDER BY (event_uid, slot, source_host, candidate_generation);

CREATE TABLE moraine.mcp_open_turns (
  session_id String, slot UInt8, generation UInt64, turn_seq UInt32,
  candidate_generation UInt64, projected_at DateTime64(3) DEFAULT now64(3)
) ENGINE = ReplacingMergeTree(generation)
PARTITION BY cityHash64(session_id) % 64
ORDER BY (session_id, slot, turn_seq, candidate_generation);

CREATE TABLE moraine.mcp_open_publication_headers (
  session_id String, candidate_publication_id String, slot UInt8, generation UInt64,
  dirty_revision UInt64, tombstone UInt8,
  required_source_heads Array(Tuple(source_host String, source_name String,
    source_file String, source_generation UInt32, publication_revision UInt64)),
  required_heads_fingerprint String, header_revision UInt64,
  prepared_at DateTime64(3) DEFAULT now64(3)
) ENGINE = ReplacingMergeTree(header_revision)
PARTITION BY cityHash64(session_id) % 64
ORDER BY (session_id, candidate_publication_id);

CREATE TABLE moraine.mcp_open_sessions (
  session_id String, slot UInt8, generation UInt64, projected_at DateTime64(3) DEFAULT now64(3)
) ENGINE = ReplacingMergeTree(generation)
ORDER BY (session_id);

CREATE TABLE moraine.mcp_open_dirty_sessions (
  session_id String, dirty_revision UInt64, observed_at DateTime64(3) DEFAULT now64(3)
) ENGINE = ReplacingMergeTree(dirty_revision) ORDER BY (session_id);

CREATE TABLE moraine.mcp_open_backfill_plans (
  session_id String, candidate_publication_id String, slot UInt8,
  candidate_generation UInt64, phase UInt8, plan_revision UInt64
) ENGINE = ReplacingMergeTree(plan_revision) ORDER BY (session_id);

CREATE TABLE moraine.v_current_published_source_generations (
  source_host String, source_name LowCardinality(String), source_file String,
  source_generation UInt32, publication_revision UInt64
) ENGINE = MergeTree ORDER BY (source_host, source_name, source_file);

