-- ===================== retirement probe fixture ==========================
-- L-RETIRE: one session with a live lineage (fp6, generation 6 published, the
-- pointer, dirty current, prepared 10 days ago) and four older headers:
--   g-stale   -> different fingerprint, stale dirty  => RETIRE
--   g-current -> different fingerprint, CURRENT dirty => keep (a reader can
--                still select it; this is the 162-header case on the host)
--   g-samefp  -> SAME fingerprint as live => keep (within-lineage; the
--                existing reclaimer owns it)
--   g-tomb    -> tombstone, different fingerprint, stale dirty, no children
--                => RETIRE, and it is a childless unit
INSERT INTO moraine.mcp_open_publication_headers
  (session_id, candidate_publication_id, slot, generation, dirty_revision, tombstone,
   required_source_heads, required_heads_fingerprint, header_revision, prepared_at) VALUES
  ('L-RETIRE', 'live',      0, 60, 900, 0, [('h','codex','/a.jsonl',6,600)], 'fp6', 60, now64(3) - toIntervalDay(10)),
  ('L-RETIRE', 'g-stale',   1, 50, 500, 0, [('h','codex','/a.jsonl',5,500)], 'fp5', 50, now64(3) - toIntervalDay(20)),
  ('L-RETIRE', 'g-current', 1, 51, 900, 0, [('h','codex','/a.jsonl',5,500)], 'fp5b',51, now64(3) - toIntervalDay(20)),
  ('L-RETIRE', 'g-samefp',  1, 52, 500, 0, [('h','codex','/a.jsonl',6,600)], 'fp6', 52, now64(3) - toIntervalDay(20)),
  ('L-RETIRE', 'g-tomb',    1, 53, 400, 1, [('h','codex','/a.jsonl',5,500)], 'fp5c',53, now64(3) - toIntervalDay(20));
INSERT INTO moraine.mcp_open_sessions (session_id, slot, generation) VALUES ('L-RETIRE', 0, 60);
