-- ============ A1B: two headers at ONE generation, and it is the live one ====
--
-- This is the P6 case, and it is why a retirement unit key is no longer
-- "some header at this generation qualifies".
--
-- `mcp_open_publication_headers` is ORDER BY (session_id, candidate_publication_id).
-- `generation` is NOT its primary key, so two publications of one session can
-- occupy one generation and both survive FINAL. The unit key the probe emits
-- is (session_id, generation) and the delete removes EVERY row at that key.
--
-- 'live'  is the pointer target: dirty 900 = dirty(S), fingerprint fpLIVE.
-- 'stale' shares generation 60, sits below the dirty revision, and carries a
--         different (but also currently published) head set, so before P6 it
--         satisfied every row-wise retirement conjunct and emitted key 60.
--
-- Measured 2026-07-28 with the pre-P6 probe: it returned `A1B 60`, and the
-- three shipped deletes left `headers 0, turns 0, events 0` for A1B while
-- mcp_open_sessions still pointed at generation 60 — the live snapshot
-- destroyed and the pointer dangling. With P6 the probe returns nothing for
-- A1B and the survivor census in expected/delete.sql shows it fully intact.
--
-- /b.jsonl@3 exists only so BOTH head sets are currently published. Without it
-- the `unpublished` CTE — which is keyed on (session_id, generation) too —
-- masks the defect by accident rather than by design.
INSERT INTO moraine.v_current_published_source_generations VALUES
  ('h', 'codex', '/b.jsonl', 3, 300);
INSERT INTO moraine.mcp_open_publication_headers
  (session_id, candidate_publication_id, slot, generation, dirty_revision, tombstone,
   required_source_heads, required_heads_fingerprint, header_revision, prepared_at) VALUES
  ('A1B', 'live',  0, 60, 900, 0, [('h','codex','/a.jsonl',6,600)], 'fpLIVE', 100, now64(3) - toIntervalDay(10)),
  ('A1B', 'stale', 0, 60, 500, 0, [('h','codex','/a.jsonl',6,600),('h','codex','/b.jsonl',3,300)], 'fpOLD', 50, now64(3) - toIntervalDay(20));
INSERT INTO moraine.mcp_open_sessions (session_id, slot, generation) VALUES ('A1B', 0, 60);
INSERT INTO moraine.mcp_open_dirty_sessions (session_id, dirty_revision) VALUES ('A1B', 900);
-- The LIVE snapshot's children, written 10 days ago: an old but perfectly live
-- session, so the child horizon does not hold the unit back either.
INSERT INTO moraine.mcp_open_events (event_uid, slot, generation, candidate_generation, session_id, projected_at) VALUES
  ('a1', 0, 60, 60, 'A1B', now64(3) - toIntervalDay(10)),
  ('a2', 0, 60, 60, 'A1B', now64(3) - toIntervalDay(10));
